        s0 = S1 * x0;
        s1 = S2 * x0;
        s2 = S3 * x1;
        s3 = S4 * x2;
        s4 = S1 * x2;
        s5 = S2 * x3;
        s6 = S4 * x3;
        s7 = (x0 - x2 + x3);

        s0 = s0 + s3 + s5;
        s1 = s1 - s4 - s6;
        s3 = s2;
        s2 = S3 * s7;

        output[0] = (Rs(s0 + s3));
        output[1] = (Rs(s1 + s3));
        output[2] = (Rs(s2));
